"use strict";
/* Build-integrity tests: the shipped index.html must stay in sync with
 * styles.css + app.js (regenerated by `node build.js`), and CI enforces
 * the same invariant via `git diff --exit-code` after a rebuild. */
const { test } = require("node:test");
const assert = require("node:assert/strict");
const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "..");
const read = (f) => fs.readFileSync(path.join(root, f), "utf8");

test("index.html is in sync with styles.css and app.js", () => {
  const html = read("index.html");
  const style = html.match(/<style>([\s\S]*?)<\/style>/);
  const script = html.match(/<script>([\s\S]*?)<\/script>/);
  assert.ok(style, "inline <style> block missing");
  assert.ok(script, "inline <script> block missing");
  assert.equal(style[1].trim(), read("styles.css").trim(), "stale styles — run `node build.js`");
  assert.equal(script[1].trim(), read("app.js").trim(), "stale script — run `node build.js`");
});

test("dashboard is self-contained (no external asset references)", () => {
  const html = read("index.html");
  assert.ok(!html.includes('src="app.js"'), 'external <script src="app.js"> found');
  assert.ok(!html.includes('href="styles.css"'), 'external <link href="styles.css"> found');
});

test("live-capture and honesty markers are wired into the dashboard", () => {
  const html = read("index.html");
  for (const marker of ['id="feed-pill"', "EventSource", "SIM_TAGGED", "web-bot-auth", "· SIM"]) {
    assert.ok(html.includes(marker), `expected marker missing: ${marker}`);
  }
});

test("v2 surfaces — event stream, rate chart, burst alert, verdicts — are present", () => {
  const html = read("index.html");
  for (const marker of [
    'id="ev-body"', 'id="ev-filters"', 'id="ev-export"',
    'id="chart-rate"', 'id="alert-banner"', 'id="hdr-verdict"',
    "SIGNATURE VALID", "pushEvent", "checkBurst", "verdict:",
  ]) {
    assert.ok(html.includes(marker), `expected marker missing: ${marker}`);
  }
  assert.ok(!/<script[^>]+src=|<link[^>]+href=/.test(html), "external asset reference found");
});

test("server.js guards side effects behind require.main and exports its pure functions", () => {
  const src = read("server.js");
  assert.match(src, /require\.main === module/);
  const exp = src.match(/module\.exports = \{([\s\S]*?)\};/);
  assert.ok(exp, "module.exports block missing");
  for (const name of [
    "classify", "parseLogLine", "verifySignedRequest", "parseSignatureInput",
    "signatureBase", "addVerificationKey", "resetCounters", "server",
  ]) {
    assert.ok(exp[1].includes(name), `export missing: ${name}`);
  }
  // no arbitrary keyid dereferencing — that would be an SSRF primitive
  assert.ok(!/fetch\s*\(|https?\.request/.test(
    src.slice(src.indexOf("RFC 9421 HTTP Message Signatures"), src.indexOf("counters = {"))
  ), "verification module must not make outbound requests");
});

test("escHtml neutralizes quotes as well as angle brackets", () => {
  // escHtml output lands inside double-quoted attributes (e.g. title="${escHtml(ev.path)}"),
  // so a raw " in a path/UA would break out of the attribute. This regressed once already.
  const src = read("app.js");
  const m = src.match(/const escHtml = .*;/);
  assert.ok(m, "escHtml definition missing");
  const escHtml = new Function(`${m[0]}; return escHtml;`)();

  for (const [input, why] of [
    ['x" onmouseover="alert(1)', "double quote in attribute context"],
    ["it's a path", "single quote"],
    ["<img src=x onerror=alert(1)>", "angle brackets"],
    ["a & b", "ampersand"],
  ]) {
    const out = escHtml(input);
    assert.ok(!/["<>]/.test(out), `unsafe output for ${why}: ${out}`);
  }
  assert.strictEqual(escHtml('"'), "&quot;");
  assert.strictEqual(escHtml("'"), "&#39;");
  assert.strictEqual(escHtml(null), "—", "nullish fallback changed");
});
